package com.logatron.processor.validate;
import com.logatron.contracts.ingestion.*;import com.logatron.processor.configuration.IngestionProperties;import com.logatron.processor.parse.ProcessingException;import org.springframework.stereotype.Component;import java.nio.charset.StandardCharsets;
@Component public class EnvelopeValidator {private final IngestionProperties p;public EnvelopeValidator(IngestionProperties p){this.p=p;}public void validate(RawLogEnvelope e){if(e==null)throw new ProcessingException("EMPTY_ENVELOPE","Envelope is required");if(e.schemaVersion()!=1)throw new ProcessingException("UNSUPPORTED_SCHEMA","Only schemaVersion 1 is supported");if(e.eventId()==null||e.observedTimestamp()==null||e.collector()==null||e.source()==null||e.resource()==null)throw new ProcessingException("INVALID_ENVELOPE","Required envelope metadata is missing");if(e.payload()==null||e.payload().isBlank())throw new ProcessingException("EMPTY_PAYLOAD","Payload is required");if(e.payload().getBytes(StandardCharsets.UTF_8).length>p.ingestion().maxEventBytes())throw new ProcessingException("EVENT_TOO_LARGE","Payload exceeds max-event-bytes");}}